import { supabase } from '@/lib/supabase';

export default async function TestPage() {
  const { data, error } = await supabase
    .from('profiles')
    .select('*')
    .limit(1);

  if (error) {
    return (
      <div className="p-8">
        <h1 className="text-red-500 font-bold">Supabase Connection Error</h1>
        <pre className="mt-4 p-4 bg-gray-100 rounded">
          {JSON.stringify(error, null, 2)}
        </pre>
      </div>
    );
  }

  return (
    <div className="p-8">
      <h1 className="text-green-500 font-bold">Supabase Connected</h1>
      <p className="mt-2 text-gray-600">Successfully queried 'profiles' table.</p>
      {data && data.length > 0 ? (
        <div className="mt-4">
          <p>Found {data.length} profile(s).</p>
        </div>
      ) : (
        <p className="mt-4 italic text-gray-500">Table is empty, but connection works.</p>
      )}
    </div>
  );
}

